        private Entry(int builderIndex, CodeRenderingContext? context)
        {
            _builderIndex = builderIndex;

            if (context is not null)
            {
                _scope = context.CodeWriter.BuildLambda(BuilderVariableName);
            }
        }

        public void Dispose()
        {
            _scope.Dispose();
        }

